#define PY_COUNT 394

// Lookup: returns pointer to char_table data for pinyin, or NULL
// Data format: [count(1B)] [char_utf8(NUL)] [char_utf8(NUL)] ...
static inline const uint8_t* py_lookup(const char* pinyin) {
    int lo = 0, hi = PY_COUNT - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        const char* s = (const char*)(PY_STRINGS + PY_OFFSETS[mid]);
        int cmp = strcmp(pinyin, s);
        if (cmp == 0) return CHAR_TABLE + CHAR_OFFSETS[mid];
        if (cmp < 0) hi = mid - 1;
        else lo = mid + 1;
    }
    return NULL;
}
